contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint minSum, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient test balance");

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;

        uint balanceBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalanceBefore = address(c).balance;
        uint testBalanceBefore = address(this).balance;

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balanceAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalanceAfter = address(c).balance;
        uint testBalanceAfter = address(this).balance;

        assert(
            balanceAfter <= balanceBefore
            && (reverted
                ? (balanceAfter == balanceBefore && cBalanceAfter == cBalanceBefore)
                : (balanceBefore >= minSum && balanceBefore >= collectAmount
                    ? (balanceAfter == balanceBefore - collectAmount
                        && cBalanceAfter == cBalanceBefore - collectAmount
                        && testBalanceAfter == testBalanceBefore + collectAmount)
                    : (balanceAfter == balanceBefore && cBalanceAfter == cBalanceBefore)))
        );
    }

    receive() external payable {}
}

