pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 depositAmount, uint256 minSum, uint256 collectAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.Deposit{value: depositAmount}() {} catch { return; }
        try c.SetMinSum(minSum) {} catch { return; }
        uint256 balanceBefore;
        try c.balances(address(this)) returns (uint256 __r) { balanceBefore = __r; } catch { return; }
        uint cBalanceBefore = address(c).balance;
        uint testBalanceBefore = address(this).balance;
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balanceAfter;
        try c.balances(address(this)) returns (uint256 __r) { balanceAfter = __r; } catch { return; }
        uint cBalanceAfter = address(c).balance;
        uint testBalanceAfter = address(this).balance;
        assertTrue(balanceAfter <= balanceBefore
            && (reverted
                ? (balanceAfter == balanceBefore && cBalanceAfter == cBalanceBefore)
                : (balanceBefore >= minSum && balanceBefore >= collectAmount
                    ? (balanceAfter == balanceBefore - collectAmount
                        && cBalanceAfter == cBalanceBefore - collectAmount
                        && testBalanceAfter == testBalanceBefore + collectAmount)
                    : (balanceAfter == balanceBefore && cBalanceAfter == cBalanceBefore))));
    }

    function testFuzz_run(uint256 depositAmount, uint256 minSum, uint256 collectAmount) public {
        _run(depositAmount, minSum, collectAmount);
    }

    receive() external payable {}
}
